SELECT ITE.NUNOTA, CAB.DTENTSAI, CAB.AD_NUMPS, ITE.CODPROD, PRO.DESCRPROD, PRO.CODVOL, (ITE.QTDNEG - ITE.QTDENTREGUE) AS RESERVADO, TOP.DESCROPER, CUS.DESCRCENCUS
FROM TGFPRO PRO LEFT JOIN TGFITE ITE ON PRO.CODPROD = ITE.CODPROD LEFT JOIN TGFCAB CAB ON ITE.NUNOTA = CAB.NUNOTA LEFT JOIN TGFTOP TOP ON (CAB.CODTIPOPER = TOP.CODTIPOPER AND CAB.DHTIPOPER = TOP.DHALTER) LEFT JOIN TSICUS CUS ON CAB.CODCENCUS = CUS.CODCENCUS
WHERE ITE.PENDENTE = 'S' AND ITE.STATUSNOTA = 'L' AND ITE.CODPROD = :A_CODPROD and CAB.TIPMOV = 'J' and (ITE.CODLOCALORIG = :P_LOCAL OR :P_LOCAL IS NULL)
ORDER BY ITE.NUNOTA
